    "name": "Licor de naranja El Penjat",
    "category": "BODEGA GOURMET",
    "description": "El Penjat es un tronjó, un licor de naranja elaborado siguiendo una receta casera muy especial que se ha recuperado para que no caiga en el olvido. Elaborado y embotellado Para hacerlo hay que colgar las naranjas sobre el aguardiente, sin que entren en contacto. De este modo, los vapores del alcohol capturan el aroma, el gusto y el color de naranja lentamente y sin tocarse. Elaborado y embotellado por la cooperativa Tres Sillas en Arbeca en obrador compartido con La Soberana Coop. Tres Sillas es una cooperativa sin ánimo de lucro de desarrollo local que elabora licores artesanos de calidad, comparte su obrador con otros proyectos agroecológicos e impulsa la economía social y solidaria a Poniente. Los ingredientes Para hacerlo utilizan ingredientes de la máxima calidad: naranjas de Tierras del Ebro, aguardiente 100% de trigo y azúcar de comercio justo. Nota de cata De color dorado y sutil aroma de naranja, debido a este proceso de elaboración. En boca el gusto cítrico toma todo el protagonismo, en perfecto equilibrio entre la dulzura y la graduación alcohólica. Graduación: 27°Sucre: 200 gr/L",
