    "category": "BODEGA GOURMET",
    "description": "La Penjada es la primera ratafia cooperativa, elaborada con aguardiente de vino aromatizado siguiendo el método tradicional del tronjó. Antes de añadir los ingredientes indispensables de toda ratafia catalana (nueces verdes, plantas aromáticas y especies) aromatizan el alcohol colgando encima naranjas en suspensión. Una receta innovadora que le aporta su carácter único (marcado también por la poca cantidad de azúcar que lleva, solo el 16%). Los ingredientes Para hacerlo utilizan ingredientes de la máxima calidad: aguardiente de vino, plantas aromáticas y especies ecológicas, azúcar de comercio justo. Nota de cata En vista presenta el aspecto habitual de una ratafia, las sorpresas llegan cuando la probamos. De aroma cítrico en nariz y entrada fresca en boca, despliega con el tiempo un contraste equilibrado entre la amargura de la nuez y la presencia de plantas aromáticas. La poca cantidad de azúcar la hace ideal para compartir en vermuts y sobremesas. Elaborada y embotellada por la cooperativa Tres Sillas en Arbeca en obrador compartido con La Soberana Coop. Tres Sillas es una cooperativa sin ánimo de lucro de desarrollo local que elabora licores artesanos de calidad, comparte su obrador con otros proyectos agroecológicos e impulsa la economía social y solidaria a Poniente. Graduación: 24°Sucre: 160 gr/LIngredientes: Aguardiente de origen vínico, nueces verdes, selección de hierbas y azúcar",
