    "description": "Siguiendo la fórmula que ya hacían nuestros tatarabuelos a principios del siglo pasado, seleccionamos de los cerdos más grandes las carnes más magras, que le dan esta tonalidad más oscura y un sabor único y especial. Sin Gluten y sin huevo Notas de cata Aun siendo muy magra, la textura es melosa y al paladar se muestra sabrosa. Recomendación de consumo Cortar en finas rodajas. Ideal para el aperitivo, en un bocadillo o con una tostada de pan con aceite de oliva extra virgen. Ingredientes Carne magra y panceta de cerdo, sal, almidón de maíz, lactosa, proteínas de leche, estabilizante (e-420i), vino (contiene sulfitos), especias y aromas, antioxidante (e-316) conservantes (e-250, e252) y colorante natural (e-120). Ingredientes Carne magra y panceta de cerdo, sal, almidón de maíz, lactosa, proteínas de leche, estabilizante (e-420i), vino (contiene sulfitos), especias y aromas, antioxidante (e-316) conservantes (e-250, e252) y colorante natural (e-120). Antes de consumir Poner a temperatura ambiente 30 minutos antes de consumir. Conservación En un lugar fresco y seco, sin exposición directa a la luz solar. Consumo preferente Una vez recibido, consumir antes de 30 días. Recomendación de consumo Cortar en finas rodajas. Ideal para el aperitivo, en un bocadillo o con una tostada de pan con aceite de oliva extra virgen.",
