    "description": "Un surtido selecto de turrones que combina sabores y texturas únicas: Xips: Un praliné de almendra con cobertura de chocolate con leche y patatas chips, bañado en cobertura negra y decorado con un toque de sal Maldon, que aporta un contraste sorprendente y crujiente. Taronja: Trufado de chocolate negro con naranja triturada, decorado con dados de naranja bañados en cobertura negra, que ofrece un sabor fresco y afrutado. Salat: Praliné de almendra y praliné de cacahuete, ambos con cobertura de chocolate con leche, bañados en cobertura negra y decorados con maíz, cacahuetes y sal Maldon, creando un equilibrio perfecto entre dulce y salado. Gerds: Trufado de frambuesa elaborado con cobertura negra, bañado en chocolate negro y decorado con frambuesa liofilizada, que aporta un toque afrutado y ligeramente ácido. Cafè: Trufado de café con cobertura negra, recubierto de chocolate con leche y decorado con granos de café de chocolate, ideal para los amantes del café. Cruixent: Turrón de gianduja de avellana con arroz crujiente, bañado en cobertura negra y decorado con perlas de caramelo salado, que ofrece una textura única y deliciosa. Contiene gluten. Un surtido pensado para satisfacer todos los gustos, desde lo dulce y cremoso hasta lo crujiente y salado, con un toque de sofisticación y creatividad en cada bocado.",
