    "description": "Rosa de chocolate El Rosal Del obrador de galletas El Rosal de Tàrrega, la rosa de galleta y chocolate está hecha a mano con ingredientes de calidad y proximidad. Un detalle original y diferente para celebrar San Jorge. Con la compra de estas rosas estás contribuyendo con un proyecto de economía social que da ocupación a personas con discapacidad o en riesgo de exclusión. El obrador es un espacio de trabajo inclusivo donde ponen en valor las capacidades de las personas que trabajan. Ingredientes: agua, harina de trigo, azúcar, cobertura de cacao (20%) [pasta de cacao, azúcar, manteca de cacao, emulgente (lecitina de soja)], huevos frescos, mantequilla, aceite vegetal (*girasol), aroma de vainillina, sal y antioxidante natural (E306). Cacao mínimo al chocolate: 64.5% Peso limpio: 180 *gr Contenido: 1 unidad NOTA: PRODUCTO BAJO ENCARGO, NO SE ACEPTAN DEVOLUCIONES. PEDIDOS A PARTIR DEL DIA 21/0/23 SOLO CON OPCIÓN DE RECOGIDA EN TIENDA.",
